using System;using EmberBastion;
class PlacementCoverageChecks {static int Main(){try{for(int field=0;field<Balance.Fields.Length;field++)for(int kind=0;kind<4;kind++){int recommended=0;for(int slot=0;slot<Balance.Fields[field].Slots.Length;slot++){int a=PlacementCoverage.Grade(field,kind,slot),b=PlacementCoverage.Grade(field,kind,slot);if(a!=b||field==0&&a!=-1||field>0&&(a<0||a>2))throw new Exception("invalid grade");if(PlacementCoverage.Recommended(field,kind,slot))recommended++;}if(field>0&&recommended!=3||field==0&&recommended!=0)throw new Exception("recommendation count");}Console.WriteLine("PASS coverage cache, grades and exactly three portrait recommendations");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
